svg.script:
//!export-start
let _pn_level = 50;
let _pn_min = 0;
let _pn_max = 100;
let _ps_label = 'WATER TANK';
let _ps_unit = '%';
let _pc_water = '#1aa7e8';
let _pc_water_dark = '#126da3';
//!export-end

let tankAnimationFrame = null;
let tankLastTime = null;
let wavePhase = 0;
let latestPct = 0;

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function toNumber(value, fallback) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function setText(el, text) {
  if (!el) return;
  while (el.firstChild) {
    el.removeChild(el.firstChild);
  }
  el.appendChild(document.createTextNode(text));
}

function postValue(id, value) {
  console.error('Not defined!', id, value);
}

function percentFromLevel() {
  const min = toNumber(_pn_min, 0);
  const max = toNumber(_pn_max, 100);
  const range = max - min || 100;
  return clamp(((toNumber(_pn_level, min) - min) / range) * 100, 0, 100);
}

function wavePath(y, left, right, amp, phase) {
  const steps = 20;
  let d = 'M' + left + ' ' + (y + Math.sin(phase) * amp).toFixed(2);
  for (let i = 1; i <= steps; i += 1) {
    const x = left + (right - left) * i / steps;
    const currentY = y + Math.sin(phase + i * 0.82) * amp;
    d += ' L' + x.toFixed(2) + ' ' + currentY.toFixed(2);
  }
  return d;
}

function drawWater(pct) {
  const topY = 45;
  const bottomY = 184;
  const usableHeight = bottomY - topY;
  const surfaceY = bottomY - usableHeight * pct / 100;
  const left = 48;
  const right = 132;
  const edgeLimiter = Math.min(pct, 100 - pct);
  const waveAmp = pct <= 0 ? 0 : clamp(1.8 + edgeLimiter * 0.08, 1.8, 4);
  const waterShape = document.getElementById('waterShape');
  const waterSurface = document.getElementById('waterSurface');
  const waterShine = document.getElementById('waterShine');

  if (pct <= 0) {
    if (waterShape) waterShape.setAttribute('d', '');
    if (waterSurface) waterSurface.setAttribute('d', '');
    if (waterShine) waterShine.setAttribute('d', '');
  } else {
    const surface = wavePath(surfaceY, left, right, waveAmp, wavePhase);
    const body = surface +
      ' L' + right + ' 184 C' + right + ' 194 ' + left + ' 194 ' + left + ' 184 Z';
    const cap = surface +
      ' C' + (right - 12) + ' ' + (surfaceY + 9) + ' ' + (left + 12) + ' ' + (surfaceY + 9) + ' ' + left + ' ' + surfaceY + ' Z';
    const shine = 'M61 ' + Math.max(surfaceY + 10, 57) + ' L72 ' + Math.max(surfaceY + 7, 54) +
      ' L72 190 L61 193 Z';

    if (waterShape) {
      waterShape.setAttribute('d', body);
      waterShape.setAttribute('fill', _pc_water || '#1aa7e8');
    }
    if (waterSurface) {
      waterSurface.setAttribute('d', cap);
      waterSurface.setAttribute('fill', _pc_water_dark || '#126da3');
      waterSurface.setAttribute('opacity', pct >= 96 ? '0.55' : '0.88');
    }
    if (waterShine) waterShine.setAttribute('d', shine);
  }
}

function stopTankAnimation() {
  if (tankAnimationFrame !== null) {
    cancelAnimationFrame(tankAnimationFrame);
    tankAnimationFrame = null;
  }
  tankLastTime = null;
}

function tankTick(timestamp) {
  if (latestPct <= 0) {
    stopTankAnimation();
    return;
  }

  const elapsed = tankLastTime === null ? 16 : timestamp - tankLastTime;
  tankLastTime = timestamp;
  wavePhase = (wavePhase + elapsed * 0.006) % (Math.PI * 2);
  drawWater(latestPct);
  tankAnimationFrame = requestAnimationFrame(tankTick);
}

function startTankAnimation() {
  if (tankAnimationFrame === null) {
    tankLastTime = null;
    tankAnimationFrame = requestAnimationFrame(tankTick);
  }
}

function render() {
  const pct = percentFromLevel();
  const valueText = document.getElementById('valueText');
  const labelText = document.getElementById('labelText');

  latestPct = pct;
  drawWater(pct);
  if (pct > 0) {
    startTankAnimation();
  } else {
    stopTankAnimation();
  }
  setText(valueText, Math.round(pct) + (_ps_unit || '%'));
  setText(labelText, _ps_label || '');
}

function putValue(id, value) {
  if (id === '_pn_level') {
    _pn_level = toNumber(value, _pn_level);
  } else if (id === '_pn_min') {
    _pn_min = toNumber(value, _pn_min);
  } else if (id === '_pn_max') {
    _pn_max = toNumber(value, _pn_max);
  } else if (id === '_ps_label') {
    _ps_label = String(value ?? '');
  } else if (id === '_ps_unit') {
    _ps_unit = String(value ?? '%');
  } else if (id === '_pc_water') {
    _pc_water = String(value ?? '#1aa7e8');
  } else if (id === '_pc_water_dark') {
    _pc_water_dark = String(value ?? '#126da3');
  }
  render();
}

render();
